for (const [k, v] of Object.entries(r.categories)) {
  console.log(String(Math.round(v.score * 100)).padStart(4), k);
}

console.log("\n=== METRICS ===");
for (const m of [
  "first-contentful-paint",
  "largest-contentful-paint",
  "total-blocking-time",
  "cumulative-layout-shift",
  "speed-index",
]) {
  const a = r.audits[m];
  if (a) {
    console.log((a.displayValue || "").padStart(9), "score=" + a.score, m);
  }
}

console.log("\n=== FAILING WEIGHTED AUDITS ===");
let any = false;
for (const [cid, c] of Object.entries(r.categories)) {
  for (const ref of c.auditRefs) {
