async () => {
  const entries = [];
  const po = new PerformanceObserver((l) => {
    for (const e of l.getEntries()) {
      entries.push({ t: Math.round(e.startTime), size: e.size, tag: e.element?.tagName, cls: (e.element?.className || '').slice(0, 45) });
    }
  });
  po.observe({ type: 'largest-contentful-paint', buffered: true });
  await new Promise(r => setTimeout(r, 400));
  const fontTimes = performance.getEntriesByType('resource')
    .filter(r => r.name.includes('.woff2'))
    .map(r => ({ f: r.name.split('/').pop().slice(0, 28), start: Math.round(r.startTime), end: Math.round(r.responseEnd) }));
  const paints = performance.getEntriesByType('paint').map(p => ({ n: p.name, t: Math.round(p.startTime) }));
  return { lcpCandidates: entries, fonts: fontTimes, paints };
}

