() => {
  // Which Switzer weights are actually demanded by rendered, non-mono text?
  const demanded = new Set();
  const mono = new Set();
  for (const el of document.querySelectorAll('*')) {
    if (!el.textContent?.trim()) continue;
    const cs = getComputedStyle(el);
    if (!cs.fontFamily) continue;
    const w = cs.fontWeight;
    if (/mono|JetBrains/i.test(cs.fontFamily)) mono.add(w);
    else if (/switzer/i.test(cs.fontFamily)) demanded.add(w);
  }
  return {
    switzerWeightsUsed: [...demanded].sort(),
    monoWeightsUsed: [...mono].sort(),
    loadedFaces: [...document.fonts].filter(f => f.status === 'loaded').map(f => f.family + ':' + f.weight),
  };
}

