  await new Promise(r => setTimeout(r, 3000));
  const og = performance.getEntriesByType('resource').filter(r => r.name.includes('/api/og'));
  return {
    step: 'after submitting a new title',
    ogFetches: og.length,
    lastUrl: decodeURIComponent(og.at(-1)?.name.split('?')[1] ?? ''),
    stillRendering: !!document.querySelector('img[src^="blob:"]'),
  };
}

